func setupHandlers(s *Server) {
	// Pages
	s.Mux().HandleFunc(
		"GET /not-found/{$}",
		pageError404Handlers{s}.GET)
	s.Mux().HandleFunc(
		"GET /",
		pageIndexHandlers{s}.GET)
	s.Mux().HandleFunc(
		"GET /_$/{$}",
		pageIndexHandlers{s}.GETStream)
	s.Mux().HandleFunc(
		"GET /item/{id}/{$}",
		pageItemHandlers{s}.GET)
	s.Mux().HandleFunc(
		"GET /item/{id}/_$/{$}",
		pageItemHandlers{s}.GETStream)
	s.Mux().HandleFunc(
		"PUT /{id}/{$}",
		appHandlers{s}.PUTEdit)
	s.Mux().HandleFunc(
		"POST /{$}",
		pageIndexHandlers{s}.POSTCreate)
	s.Mux().HandleFunc(
		"POST /filter/{$}",
		pageIndexHandlers{s}.POSTFilter)
	s.Mux().HandleFunc(
		"DELETE /item/{id}/{$}",
		pageItemHandlers{s}.DELETEItem)
}

func (s *Server) httpErrIntern(
	w http.ResponseWriter, _ *http.Request,
	sse *datastar.ServerSentEventGenerator, msg string, err error,
) {
	s.LogErr(msg, err)
	if sse != nil {
		// The stream is open, hence no status is left to send.
		return
	}
	if httpserve.ResponseBodyWritten(w) {
		// A status written now only appends its text to the body.
		return
	}
	httpserve.WriteErrStatus(w, err)
}

func (s *Server) render404(w http.ResponseWriter, r *http.Request) {
	p := dpapp.PageError404{
		App: s.app,
	}

	defer s.recoverPanic(w, r, nil, "PageError404.GET")
	body, redirect := p.GET(r)
	if httpserve.Redirect(w, r, redirect) {
		return
	}
	genericHead := s.app.Head(r)

	bodyAttrs := func(w http.ResponseWriter) {
		httpserve.WriteReloadOnVisibility(w)
	}
	w.WriteHeader(http.StatusNotFound)
	if err := s.writeHTML(
		w, r, genericHead, nil, body, bodyAttrs, nil,
	); err != nil {
		s.LogErr("rendering PageError404", err)
		return
	}
}

type appHandlers struct{ *Server }

func (s appHandlers) PUTEdit(w http.ResponseWriter, r *http.Request) {
	if !s.CheckDatastarRequest(w, r) {
		return
	}

	httpserve.LimitRequestBody(w, r, s.BodySizeLimit())
	var signals datapages.Signals[struct {
		Title       string `json:"title"`
		Description string `json:"description"`
		Done        bool   `json:"done"`
		Due         string `json:"due"`
	}]
	if err := datastar.ReadSignals(r, &signals.Values); err != nil {
		s.HTTPErrBad(w, "reading signals", err)
		return
	}

	var query datapages.Query[struct {
		Toggle bool `query:"toggle"`
	}]
	{
		if q := httpread.QueryValue(r.URL.RawQuery, "toggle"); q != "" {
			b, err := strconv.ParseBool(q)
			if err != nil {
				s.HTTPErrBad(w, "unexpected value for query parameter: toggle", err)
				return
			}
			query.Values.Toggle = b
		}
	}

	var path datapages.Path[struct {
		ID string `path:"id"`
	}]
	path.Values.ID = r.PathValue("id")

	dispatchTodoUpdated := dispatcherEventTodoUpdated{s: s.Server, ctx: r.Context()}
	defer s.recoverPanic(w, r, nil, "App.Edit")
	err := s.app.PUTEdit(r, path, query, signals, dispatchTodoUpdated)
	if err != nil {
		s.httpErrIntern(w, r, nil, "handling action App.Edit", err)
		return
	}
}

